import{_ as a,b as e,c as r,I as o}from"./chunks/framework.C6cPs9Ia.js";const n="/LQY/images/portrait.jpg",g=JSON.parse('{"title":"关于本站","description":"关于柳卿烟和这个小站——一名普通高中生的博客","frontmatter":{"title":"关于本站","date":"2026-09-16T00:00:00.000Z","tags":["关于"],"head":[["meta",{"name":"description","content":"关于柳卿烟和这个小站——一名普通高中生的博客"}],["meta",{"name":"keywords","content":"关于, 柳卿烟, 高中生, 博客"}]]},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),i={name:"about.md"};function s(l,t,d,h,p,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<p><img src="'+n+'" alt="" data-fancybox="gallery"></p><h2 id="你好-这里是柳卿烟" tabindex="-1">你好，这里是柳卿烟 <a class="header-anchor" href="#你好-这里是柳卿烟" aria-label="Permalink to &quot;你好，这里是柳卿烟&quot;">​</a></h2><p>一名高二学生，坐标某个夏天很热、冬天很冷的城市。</p><p>白天的课表是数学、物理、英语轮番上场；放学之后的时间属于自己——看动画、打游戏、听歌，偶尔折腾一下这个网站。</p><p>概括一下：在题海和课余爱好之间找平衡，两边都不想放弃。</p><h2 id="兴趣爱好" tabindex="-1">兴趣爱好 <a class="header-anchor" href="#兴趣爱好" aria-label="Permalink to &quot;兴趣爱好&quot;">​</a></h2><ul><li><strong>动画</strong>：每季追 3-5 部，习惯三集定去留，观后感会发在站里</li><li><strong>游戏</strong>：QQ 飞车玩了挺久，偶尔怀旧一下小学的网页游戏</li><li><strong>喜欢的画师</strong>：甘城なつき（Nachoneko），她的原创角色猫羽雫是我用了很久的壁纸来源</li><li><strong>音乐</strong>：歌单按心情分类，公交上的 23 分钟必须有 BGM</li><li><strong>瞎折腾</strong>：HTML/CSS/Python 三脚猫水平，最大的成果就是这个站</li></ul><h2 id="本站简史" tabindex="-1">本站简史 <a class="header-anchor" href="#本站简史" aria-label="Permalink to &quot;本站简史&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时期</th><th>形态</th></tr></thead><tbody><tr><td>一代目</td><td>手写静态页，纯 HTML+CSS，丑但真诚</td></tr><tr><td>二代目</td><td>Astro + Mizuki 主题</td></tr><tr><td>三代目</td><td>VitePress 魔改主题，现在这个样子</td></tr></tbody></table><p>域名用的是 GitHub Pages（<code>liu-qinyan.github.io/LQY</code>），托管在 GitHub 上，全部源码也在同一个仓库里。看板娘、点击特效、背景音乐都是自己动手改的，欢迎右键查看源码。</p><h2 id="一些问答" tabindex="-1">一些问答 <a class="header-anchor" href="#一些问答" aria-label="Permalink to &quot;一些问答&quot;">​</a></h2><p><strong>Q：为什么主题是蓝色的？</strong> A：个人喜好。蓝色看着舒服，配色、图标、看板娘都是照这个方向搭的。</p><p><strong>Q：为什么不太玩手游了？</strong> A：玩过，后来发现自己更喜欢&quot;上车就能跑一圈&quot;这种节奏快的游戏，单局短，不黏人，适合学生的时间表。</p><p><strong>Q：更新的动力是？</strong> A：评论区的每一条留言，和&quot;又活过了一场月考&quot;的仪式感。</p><p><strong>Q：可以转载文章吗？</strong> A：可以，注明作者和原文地址即可。商业用途不行。</p><p><strong>Q：怎么联系？</strong> A：评论区留言最快；也可以在 <a href="https://github.com/liu-qinyan" target="_blank" rel="noreferrer">GitHub</a> 提 issue。</p><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>如果屏幕前的你也是&quot;白天上课、晚上有自己的小世界&quot;的同款学生—— 平衡好学习和爱好，两边的快乐都别放弃。</p><p>月考周会断更，但小站一直都在，放学后见。</p>',19)])])}const b=a(i,[["render",s]]);export{g as __pageData,b as default};
